import { readFileSync, writeFileSync } from 'node:fs';
const mapping = JSON.parse(readFileSync('team-ownership.json', 'utf8'));
const valid = /^[a-zA-Z0-9][a-zA-Z0-9-]*$/;
if (!valid.test(mapping.lead)) throw new Error('Set a valid lead GitHub username.');
const assigned = new Set();
let value =
  '# Generated by npm run team:owners. Lead controls this mapping.\n# Review enforcement depends on GitHub plan; this is not a folder write lock.\n';
value += `* @${mapping.lead}\n`;
for (const role of ['admin', 'teacher', 'student', 'parent']) {
  const members = mapping.roles[role];
  if (!Array.isArray(members) || members.some((user) => !valid.test(user)))
    throw new Error(`Invalid members for ${role}`);
  for (const member of members) {
    if (assigned.has(member.toLowerCase())) throw new Error('Assign each developer to one role.');
    assigned.add(member.toLowerCase());
  }
  if (members.length)
    value += `/src/features/${role}/ @${mapping.lead} ${members.map((user) => '@' + user).join(' ')}\n`;
}
writeFileSync('.github/CODEOWNERS', value);
console.log('CODEOWNERS updated. The lead should commit this together with team-ownership.json.');
